// ---------- Voetbal IQ: Wat doe jij? ----------
IQ_QUIZ.push(
  {q:"Je bent middenvelder en je krijgt de bal met veel ruimte. Wat doe je eerst?", options:["Meteen terugspelen","Kijken of een spits vrij loopt","De bal stil laten liggen"], answer:1, why:"Met ruimte kun je het spel vooruit brengen. Kijk eerst naar je aanvallers."},
  {q:"Een tegenstander dribbelt op je af in je eigen strafschopgebied. Wat doe je?", options:["Een sliding maken","Op de been blijven en hem naar buiten sturen","Weglopen"], answer:1, why:"Een sliding in je eigen strafschopgebied kan een penalty opleveren."},
  {q:"Je team krijgt een hoekschop. Waar ga je staan als je klein bent?", options:["Op de eerste paal","Rand van het strafschopgebied voor de tweede bal","In de goal"], answer:1, why:"Kleine spelers zijn vaak goed in het oppikken van de tweede bal."},
  {q:"Je staat buitenspel. Wat doe je?", options:["Stilstaan en meedoen als de bal komt","Snel terug onside lopen","Juichen"], answer:1, why:"Door terug te lopen kun je weer meedoen zonder buitenspel."},
  {q:"Je bent keeper en de bal is ver weg. Wat doe je?", options:["Op de doellijn blijven staan","Een stuk naar voren komen om ballen achter je verdediging op te vangen","Gaan zitten"], answer:1, why:"Een keeper die meespeelt, kan ballen achter de verdediging onderscheppen."},
  {q:"Je team verliest de bal en jij bent ver weg. Wat doe je?", options:["Stilstaan","Terug naar je positie sprinten","Naar de bal lopen"], answer:1, why:"Iedereen moet terug naar zijn positie zodat het team compact is."},
  {q:"Je wordt gewisseld. Hoe loop je van het veld?", options:["Langzaam en boos","Snel, via de dichtstbijzijnde lijn, met een high five","Over het midden"], answer:1, why:"Snel van het veld helpt je team en de high five laat zien dat je een teamspeler bent."},
  {q:"Jouw team is in balbezit en jij bent centrale verdediger. Wat doe je?", options:["Ver naar voren lopen","Breed gaan staan en aanspeelbaar zijn","Achter de keeper staan"], answer:1, why:"Als verdediger help je de opbouw door aanspeelbaar te zijn."},
  {q:"Je krijgt een lange bal en een verdediger staat naast je. Wat doe je?", options:["Je lichaam ertussen zetten","Wachten tot hij hem pakt","Wegkijken"], answer:0, why:"Met je lichaam tussen bal en tegenstander win je het duel."},
  {q:"Je hebt de bal bij de zijlijn en twee tegenstanders komen eraan. Wat doe je?", options:["Proberen om ze allebei heen","Snel terugspelen of breed naar binnen","De bal uitschieten"], answer:1, why:"Met twee tegen één verlies je de bal snel. Speel hem naar een vrije teamgenoot."},
  {q:"Er is een penalty voor jouw team. Wat doen de andere spelers?", options:["Juichen bij de middenlijn","Klaarstaan aan de rand van het strafschopgebied voor een rebound","Weglopen"], answer:1, why:"Als de keeper de bal tegenhoudt, kan een teamgenoot de rebound pakken."},
  {q:"Je bent aanvaller en de tegenstander heeft de bal bij zijn keeper. Wat doe je?", options:["Stilstaan","Druk zetten zodat hij snel moet spelen","Terug naar je eigen goal"], answer:1, why:"Door druk te zetten dwing je de tegenstander tot fouten."},
  {q:"Je trainer zegt 'compact'. Wat bedoelt hij?", options:["Dicht bij elkaar staan","Ver uit elkaar staan","Snel rennen"], answer:0, why:"Compact betekent dicht bij elkaar, zodat er weinig ruimte is."},
  {q:"Je trainer zegt 'breed'. Wat bedoelt hij?", options:["Naar het midden komen","Naar de zijlijnen gaan","Gaan zitten"], answer:1, why:"Breed spelen maakt het veld groot bij balbezit."},
  {q:"Je speelt een pass die te zacht is en wordt onderschept. Wat leer je ervan?", options:["Nooit meer passen","Lange passes harder spelen","Alleen nog dribbelen"], answer:1, why:"Een pass over een langere afstand moet harder om aan te komen."},
  {q:"Je bent geblesseerd tijdens de wedstrijd. Wat doe je?", options:["Doorspelen met pijn","Het aangeven en stoppen","Niemand iets zeggen"], answer:1, why:"Met een blessure doorspelen kan het erger maken."},
  {q:"Je staat 3-0 voor. Hoe speel je?", options:["De tegenstander uitlachen","Sportief blijven en geconcentreerd doorspelen","Stoppen met rennen"], answer:1, why:"Respect en concentratie blijven belangrijk, ook als je voorstaat."},
  {q:"Je krijgt de bal tussen de linies. Wat is slim?", options:["Draaien en vooruit kijken","Meteen terugspelen","De bal stil laten liggen"], answer:0, why:"Tussen de linies heb je vaak ruimte om te draaien en het spel te versnellen."},
  {q:"De verdediger staat heel hoog. Wat doe je als spits?", options:["Ook hoog blijven staan","Een loopactie maken achter de verdediging","Naar je eigen helft lopen"], answer:1, why:"Een hoge verdediging laat ruimte achter zich."},
  {q:"Je team staat onder druk en jij hebt de bal op je eigen helft. Wat is veilig?", options:["Een moeilijke dribbel","Een simpele pass naar een vrije teamgenoot","De bal achterwaarts naar je eigen goal schieten"], answer:1, why:"Onder druk is simpel en zeker het beste."},
  {q:"Je bent vleugelspeler en je back loopt mee naar voren. Wat doe je?", options:["Naar binnen gaan zodat hij de ruimte aan de zijkant krijgt","Hem in de weg lopen","Stoppen"], answer:0, why:"Door naar binnen te gaan maak je ruimte voor je back op de flank."},
  {q:"De tegenstander neemt een snelle ingooi. Wat doe je?", options:["Rustig blijven staan","Snel je man oppakken","Klagen bij de scheidsrechter"], answer:1, why:"Bij een snelle ingooi moet je meteen je tegenstander dekken."},
  {q:"Je mist een grote kans. Wat doe je in de volgende minuut?", options:["Je hoofd laten hangen","Weer vrijlopen en de bal vragen","Stoppen met schieten"], answer:1, why:"De beste spitsen blijven kansen zoeken, ook na een misser."},
  {q:"Waarom is praten op het veld belangrijk?", options:["Om de tegenstander te storen","Om je teamgenoten te helpen met wat ze niet zien","Het is niet belangrijk"], answer:1, why:"Je teamgenoten zien niet alles. Jij kunt ze helpen met korte woorden."},
  {q:"Je krijgt de bal en je weet niet wat je moet doen. Wat helpt de volgende keer?", options:["Voor de pass rondkijken","Je ogen dichtdoen","Altijd ver weg schieten"], answer:0, why:"Wie voor de pass rondkijkt, weet al wat hij gaat doen."},
  {q:"Er ligt een losse bal tussen jou en je tegenstander. Wat doe je?", options:["Wachten","Er vol voor gaan, met je lichaam ervoor","Weglopen"], answer:1, why:"Losse ballen win je met vastberadenheid en een goede lichaamshouding."},
  {q:"Je trainer zet je op een nieuwe positie. Wat doe je?", options:["Mopperen","Vragen wat hij van je verwacht en het proberen","Weigeren"], answer:1, why:"Een nieuwe positie leert je het spel van een andere kant kennen."},
  {q:"Je bent laatste man en de tegenstander rent alleen op je af. Mag je hem vasthouden?", options:["Ja, dat is slim","Nee, dat is een overtreding en vaak een rode kaart","Alleen als de scheidsrechter niet kijkt"], answer:1, why:"Vasthouden is een overtreding. Als laatste man kan dat rood opleveren."},
  {q:"Na een goal van de tegenstander, wat zegt een goede aanvoerder?", options:["Wie was dat?!","Kom op, we gaan door!","Niets"], answer:1, why:"Positief blijven helpt het team terugkomen."},
  {q:"Je bent moe in de laatste minuten. Wat is slim met de bal?", options:["Moeilijke trucjes doen","Simpel en zeker spelen","De bal wegschieten"], answer:1, why:"Als je moe bent, maak je sneller fouten. Simpel spelen helpt."},
  {q:"Wanneer is een sliding een goed idee?", options:["Altijd","Alleen als je zeker de bal raakt en het veilig is","Nooit, ook niet als het moet"], answer:1, why:"Een sliding is een laatste redmiddel. Als je mist, ben je uitgespeeld."},
  {q:"Je team speelt met hoge druk. Wat doe jij als middenvelder?", options:["Achterblijven","Meeschuiven en je man oppakken","Gaan zitten"], answer:1, why:"Hoge druk werkt alleen als het hele team meeschuift."},
  {q:"Je bent spits en de verdediger kijkt naar de bal. Wat doe je?", options:["In zijn rug lopen","Voor hem gaan staan","Niets"], answer:0, why:"Als de verdediger naar de bal kijkt, kun je in zijn rug ontsnappen."},
  {q:"Je staat in de muur bij een vrije trap. Wat doe je?", options:["Wegdraaien","Blijven staan en niet springen tenzij afgesproken","Weglopen"], answer:1, why:"Een muur moet dicht blijven, anders gaat de bal erdoorheen."},
  {q:"Je krijgt een gele kaart. Wat doe je?", options:["Ruzie maken met de scheidsrechter","Rustig blijven en voorzichtig verder spelen","Stoppen met spelen"], answer:1, why:"Na een gele kaart moet je slim spelen om geen tweede te krijgen."},
  {q:"Je hebt de bal en een teamgenoot roept 'tijd'. Wat betekent dat?", options:["Er komt iemand aan","Je hebt ruimte en tijd om rustig te kijken","Het is rust"], answer:1, why:"'Tijd' betekent: er is niemand dichtbij, je kunt rustig kijken."},
  {q:"Je team krijgt een vrije trap ver van het doel. Wat is vaak slim?", options:["Altijd direct op doel schieten","Snel een korte pass geven en opbouwen","De bal weggeven"], answer:1, why:"Van ver schieten levert weinig op. Opbouwen houdt de bal in het team."},
  {q:"De tegenstander heeft een snelle spits. Hoe sta je als verdediger?", options:["Heel hoog","Iets dieper, zodat hij geen ruimte achter je heeft","Op de middenlijn"], answer:1, why:"Door iets dieper te staan, voorkom je dat hij in je rug kan sprinten."},
  {q:"Je bent keeper en vangt de bal. Wat kijk je eerst?", options:["Naar de tribune","Of er een teamgenoot vrij staat voor een snelle aanval","Naar de grond"], answer:1, why:"Een snelle uitworp kan een counter starten."},
  {q:"Je speelt een partijtje en jouw team wint makkelijk. Wat doe je?", options:["Uitdagend gaan spelen","Je zwakke voet en nieuwe trucjes oefenen","Stoppen"], answer:1, why:"Een makkelijk partijtje is een kans om nieuwe dingen te oefenen."}
);

// ---------- Dagles: techniek ----------
